input.command:
cd /private/tmp && rm -f av_mig.db && sqlite3 av_mig.db <<'EOF'
CREATE TABLE orders (id INTEGER PRIMARY KEY, shipped_at TEXT, cancelled_at TEXT);
INSERT INTO orders (shipped_at, cancelled_at) VALUES
  ('2026-08-01', NULL),          -- shipped
  (NULL, NULL),                  -- not shipped
  ('2026-08-02', '2026-08-03'),  -- shipped THEN cancelled/returned
  (NULL, '2026-08-04');          -- cancelled before shipping
ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';
CREATE INDEX idx_orders_status ON orders(status);
UPDATE orders SET status = 'fulfilled' WHERE shipped_at IS NOT NULL;
.headers on
.mode column
SELECT * FROM orders;
SELECT 'rows changed by UPDATE', changes();
-- row inserted after migration, before app writes status:
INSERT INTO orders (shipped_at) VALUES ('2026-08-26');
SELECT id, shipped_at, status FROM orders WHERE id = 5;
EOF
echo "=== second run (re-run the migration on an already-migrated DB) ==="
sqlite3 av_mig.db <<'EOF'
ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';
EOF
sqlite3 av_mig.db "CREATE INDEX idx_orders_status ON orders(status);"
sqlite3 av_mig.db "UPDATE orders SET status = 'fulfilled' WHERE shipped_at IS NOT NULL; SELECT changes();"
rm -f av_mig.db
